{
  "title": "密林遇故人",
  "scene": "你穿行在一片幽深的密林中，四周是参天的古木，阳光透过树叶的缝隙洒下斑驳的光影。突然，一阵急促的脚步声从树林深处传来，一个身影闪现，是你多年未见的师弟。他显得十分狼狈，衣衫破烂，脸上带着惊恐之色。‘师兄，快帮我！’他急切地喊道。不远处，隐隐传来低沉的吼声，似乎有什么凶猛的野兽在追赶他。",
  "goal": "帮助师弟摆脱追击",
  "clue": "师弟的狼狈和惊恐，以及远处的低沉吼声",
  "choices": [
    {
      "id": "A",
      "text": "直接冲向野兽",
      "outcome": "你仗剑向前，准备与野兽一决高下。然而，这野兽异常凶猛，你勉强将其击退，但自己也受了轻伤。师弟感激地看着你，你们暂时安全了。",
      "result": "partial",
      "next": "next_level"
    },
    {
      "id": "B",
      "text": "寻找藏身之处",
      "outcome": "你带着师弟迅速找到一个隐蔽的山洞，野兽在洞外徘徊了一阵后离去。师弟的情绪逐渐平复，你们可以安心地休息一会儿。",
      "result": "success",
      "next": "next_level"
    },
    {
      "id": "C",
      "text": "询问师弟情况",
      "outcome": "你停下脚步，询问师弟遇到的麻烦。师弟告诉你，野兽是被他无意中激怒的。你根据他的描述，找到了一条安全的绕路，成功避开了野兽的追击。",
      "result": "success",
      "next": "next_level"
    }
  ]
}
